import rawManifest from '../../public/data/manifest.json';
import { assembleMaterials, countContent, parseManifest, parsePack } from '../content/packFormat.js';
import type { Materials } from '../content/types';

// Tests exercise the same generated files the build publishes. The migration
// fingerprint/oracle lives separately and is never regenerated by normal builds.
const files = import.meta.glob('../../public/data/packs/*.json', { eager: true, import: 'default' });
export const manifest = parseManifest(rawManifest);
export const packs = manifest.packs.map((entry) => parsePack(files[`../../public/data/${entry.url}`]));
export const realMaterials = assembleMaterials(manifest, packs);
export const contentBase = '/eng-trainer/data/';

export function contentResponses(): Map<string, unknown> {
  return new Map<string, unknown>([
    [`${contentBase}manifest.json`, manifest],
    ...manifest.packs.map((entry, i): [string, unknown] => [`${contentBase}${entry.url}`, packs[i]])
  ]);
}

export function createContentFetch(materials?: Materials): typeof fetch {
  let responses = contentResponses();
  if (materials) {
    const { meta, blocks, ...content } = materials;
    const pack = parsePack({ schemaVersion: 1, id: 'fixture', title: 'Fixture', order: 0, content });
    const url = 'packs/fixture.0000000000000000.json';
    const counts = countContent(content);
    const fixtureManifest = parseManifest({
      schemaVersion: 1, meta, blocks, counts,
      packs: [{ id: pack.id, title: pack.title, order: pack.order, url, counts }]
    });
    responses = new Map<string, unknown>([[`${contentBase}manifest.json`, fixtureManifest], [`${contentBase}${url}`, pack]]);
  }
  return async (input) => {
    const url = String(input);
    return responses.has(url)
      ? new Response(JSON.stringify(responses.get(url)), { status: 200 })
      : new Response('Not found', { status: 404 });
  };
}
